from statistics import median
from paper_testing.derived_evidence_classifier import classify_derived_evidence
from paper_testing.derived_performance_aggregator import chronological_drawdown

def build_replay_report(run,dataset,decisions,setups,outcomes,excursions,warnings=None):
    filled=[row for row in outcomes if row.get("entry_filled")];rs=[float(row["realized_r"]) for row in filled if row.get("realized_r") is not None];positive=sum(x for x in rs if x>0);negative=abs(sum(x for x in rs if x<0));evidence=classify_derived_evidence(len(filled));mfe=[float(x["mfe_r"]) for x in excursions if x.get("mfe_r") is not None];mae=[float(x["mae_r"]) for x in excursions if x.get("mae_r") is not None]
    return {"run":{"replay_run_id":run["replay_run_id"],"symbol":run["provider_symbol"],"family":run["family"],"strategy":run["requested_strategy"],"start_time":run["start_time"],"end_time":run["end_time"],"completed":run["status"]=="completed"},"dataset_quality":dataset,"decision_funnel":{"total_decisions":len(decisions),"developing_setups":sum(bool((x.get("payload") or {}).get("setup_id")) for x in decisions),"confirmed_setups":len(setups),"valid_trade_plans":len(setups),"filled_trades":len(filled),"missed_entries":sum(x.get("outcome")=="MISSED_ENTRY" for x in outcomes),"cancelled_before_fill":sum(not x.get("entry_filled") for x in outcomes)},"trade_results":{"tp1_hits":sum(bool(x.get("tp1_hit")) for x in filled),"tp2_hits":sum(bool(x.get("tp2_hit")) for x in filled),"stops":sum(bool(x.get("stop_hit")) for x in filled),"ambiguous":sum(bool(x.get("intracandle_ambiguous")) for x in filled),"average_r":sum(rs)/len(rs) if rs else None,"median_r":median(rs) if rs else None,"profit_factor":positive/negative if negative else None,"maximum_drawdown_r":chronological_drawdown(outcomes)["maximum_drawdown_r"]},"excursions":{"average_mfe_r":sum(mfe)/len(mfe) if mfe else None,"average_mae_r":sum(mae)/len(mae) if mae else None},"evidence":{"filled_trade_count":len(filled),"label":evidence["evidence_label"],"eligible_for_ranking":evidence["eligible_for_router_ranking"]},"warnings":list(warnings or [])}
